package havoc.client.runtime;

import havoc.client.runtime.distribution.DistributionCapabilities;
import net.fabricmc.loader.api.FabricLoader;

/** Build metadata resolved from the Fabric metadata generated by Gradle. */
public final class HavocBuild {
    private static final String MOD_ID = "havoc";
    private static final String FALLBACK_VERSION = "dev";
    private static volatile String cachedVersion;

    private HavocBuild() {
    }

    public static String version() {
        String cached = cachedVersion;
        if (cached != null) return cached;

        String resolved = FabricLoader.getInstance()
                .getModContainer(MOD_ID)
                .map(container -> container.getMetadata().getVersion().getFriendlyString())
                .filter(value -> value != null && !value.isBlank())
                .orElse(FALLBACK_VERSION);
        cachedVersion = resolved;
        return resolved;
    }

    public static String displayVersion() {
        String suffix = DistributionCapabilities.displaySuffix();
        return suffix.isBlank() ? version() : version() + " " + suffix;
    }

    public static boolean isDevelopmentBuild() {
        return !DistributionCapabilities.isReleaseArtifact();
    }
}
